  await fs.writeFile(testInfo.outputPath('pending-title-duplicate-role-first-unlink.json'), JSON.stringify({ ...nativeObservation, removed: removed.map(relative), survivors: survivors.map(relative), originalAdmissionGeneration: generation, deletingGeneration: authority.generation, descriptor: authority.titleRecovery }, null, 2));
  const child = app.process(), mainPid = await app.evaluate(() => process.pid), processProof = { boundary: 'capture-deletion-unlinked', wrapperPid: child.pid, mainPid, exitBoundary: 'Electron app.exit(77)' };
  const exited = new Promise(resolve => child.once('exit', (code, signal) => resolve({ code, signal })));
  const abrupt = app.evaluate(({ app: electronApp }) => electronApp.exit(77)).catch(error => { if (!/closed|disposed/i.test(error.message)) throw error; });
  processProof.wrapperExit = await exited; await abrupt;
  await expect.poll(() => { try { process.kill(mainPid, 0); return 'alive'; } catch (error) { if (error.code === 'ESRCH') return 'exited'; throw error; } }).toBe('exited');
