  await page.getByRole('button', { name: 'Refresh', exact: true }).click();
  await expect(page.getByRole('status')).toContainText('Pending title recovery contains changed or unsupported writing. Preserve it for explicit review.');
  expect(await fs.readFile(ledgerFile)).toEqual(alteredBytes); expect(await files(base)).toEqual(retainedAfterOfflineEdit);
  for (const file of survivors) expect(await observe(file)).toEqual(observations[path.relative(base, file).split(path.sep).join('/')]);
